 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_BanGiao_BaoVe ON dbo.BAN_GIAO_THUOC AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaDT=d.MaDT WHERE i.MaDT IS NULL OR d.TrangThai=N''Đã giao'' OR EXISTS('+NCHAR(13)+N''+NCHAR(10)+N' SELECT i.MaHD,i.MaPX EXCEPT SELECT d.MaHD,d.MaPX)) THROW 52121,N''Không xóa/đổi nguồn bàn giao hoặc sửa bản đã giao.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.DON_THUOC d ON d.MaDT=i.MaDT JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD JOIN dbo.PHIEU_XUAT p ON p.MaPX=i.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.VW_HOA_DON_THANH_TOAN v ON v.MaHD=h.MaHD WHERE h.PhienBanQuyTrinh<>2 OR h.TrangThai<>N''Đã xác nhận'' OR v.ConPhaiTra<>0 OR d.MaLS<>h.MaLS OR p.MaLS<>h.MaLS OR p.TrangThai<>N''Đã ghi sổ'' OR'+NCHAR(13)+N''+NCHAR(10)+N' NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_XUAT x JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=x.MaCTDT WHERE x.MaPX=i.MaPX AND c.MaDT=i.MaDT) OR'+NCHAR(13)+N''+NCHAR(10)+N' EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_XUAT x LEFT JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=x.MaCTDT WHERE x.MaPX=i.MaPX AND(c.MaDT IS NULL OR c.MaDT<>i.MaDT)))'+NCHAR(13)+N''+NCHAR(10)+N' THROW 52121,N''Bàn giao cần hóa đơn đã thu đủ, xuất ghi sổ và đơn cùng lượt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã giao'' AND NOT EXISTS(SELECT 1 FROM dbo.NHAN_VIEN n JOIN dbo.TAI_KHOAN t ON t.MaNV=n.MaNV WHERE n.MaNV=i.MaNVGiao AND (n.MaChucVu=N''CV005'' OR EXISTS(SELECT 1 FROM dbo.VAI_TRO v WHERE v.MaVaiTro=t.MaVaiTro AND UPPER(LTRIM(RTRIM(v.TenVaiTro))) IN(N''ADMIN'',N''QUẢN TRỊ''))) AND n.TrangThai=N''Đang làm việc'' AND t.TrangThai=N''Đang hoạt động''))'+NCHAR(13)+N''+NCHAR(10)+N' THROW 52121,N''Người giao phải là dược sĩ hoặc Admin đang hoạt động.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_CauHinh_BaoVe ON dbo.CAU_HINH_THUOC_KE_DON AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaThuoc=d.MaThuoc WHERE d.TrangThai<>N''Nháp'' AND'+NCHAR(13)+N''+NCHAR(10)+N' (i.MaThuoc IS NULL OR NOT((i.PhienBan=d.PhienBan AND i.TrangThai<>N''Nháp'' AND NOT EXISTS('+NCHAR(13)+N''+NCHAR(10)+N' SELECT i.MaNhomThuoc,i.DoiTuongApDung,i.DuongDung,i.LieuDungGoiY,i.HuongDanGoiY,i.MaNguoiDuyet,i.NgayDuyet'+NCHAR(13)+N''+NCHAR(10)+N' EXCEPT SELECT d.MaNhomThuoc,d.DoiTuongApDung,d.DuongDung,d.LieuDungGoiY,d.HuongDanGoiY,d.MaNguoiDuyet,d.NgayDuyet))'+NCHAR(13)+N''+NCHAR(10)+N' OR(i.PhienBan=d.PhienBan+1 AND i.TrangThai=N''Nháp'' AND i.MaNguoiDuyet IS NULL AND i.NgayDuyet IS NULL))))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52117,N''Đổi hướng dẫn đã duyệt phải lập phiên bản nháp tiếp theo và giữ lịch sử.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã duyệt'' AND NOT EXISTS('+NCHAR(13)+N''+NCHAR(10)+N' SELECT 1 FROM dbo.NHAN_VIEN n JOIN dbo.TAI_KHOAN t ON t.MaNV=n.MaNV WHERE n.MaNV=i.MaNguoiDuyet AND (n.MaChucVu IN(N''CV002'',N''CV005'') OR EXISTS(SELECT 1 FROM dbo.VAI_TRO v WHERE v.MaVaiTro=t.MaVaiTro AND UPPER(LTRIM(RTRIM(v.TenVaiTro))) IN(N''ADMIN'',N''QUẢN TRỊ''))) AND n.TrangThai=N''Đang làm việc'' AND t.TrangThai=N''Đang hoạt động''))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52117,N''Người duyệt hướng dẫn cần quyền chuyên môn đang hoạt động.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_CTKH_BaoVe ON dbo.CHI_TIET_KE_HOACH AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.KE_HOACH_DIEU_TRI k WITH(UPDLOCK,HOLDLOCK) JOIN(SELECT MaKHDT FROM inserted UNION SELECT MaKHDT FROM deleted) x ON x.MaKHDT=k.MaKHDT'+NCHAR(13)+N''+NCHAR(10)+N' WHERE k.TrangThai<>N''Nháp'' AND EXISTS(SELECT 1 FROM inserted i FULL JOIN deleted d ON d.MaCTKH=i.MaCTKH'+NCHAR(13)+N''+NCHAR(10)+N' WHERE (i.MaKHDT=k.MaKHDT OR d.MaKHDT=k.MaKHDT) AND(i.MaCTKH IS NULL OR d.MaCTKH IS NULL OR EXISTS('+NCHAR(13)+N''+NCHAR(10)+N' SELECT i.MaKHDT,i.MaDV,i.LanThu,i.SoLuongDuKien,i.DonGiaDuKien,i.GhiChu,i.NoiDungBuoc'+NCHAR(13)+N''+NCHAR(10)+N' EXCEPT SELECT d.MaKHDT,d.MaDV,d.LanThu,d.SoLuongDuKien,d.DonGiaDuKien,d.GhiChu,d.NoiDungBuoc))))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52114,N''Không thay nội dung/định lượng bước thuộc kế hoạch đã duyệt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaCTKH=d.MaCTKH WHERE EXISTS(SELECT 1 FROM dbo.DICH_VU_THUC_HIEN s WHERE s.MaCTKH=d.MaCTKH AND s.TrangThai=N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N' AND(i.MaCTKH IS NULL OR EXISTS(SELECT i.MaKHDT,i.MaDV,i.SoLuongDuKien,i.DonGiaDuKien,i.NoiDungBuoc EXCEPT SELECT d.MaKHDT,d.MaDV,d.SoLuongDuKien,d.DonGiaDuKien,d.NoiDungBuoc)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52114,N''Bước đã thực hiện không sửa nguồn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_CTMau_BaoVe ON dbo.CHI_TIET_MAU_KE_HOACH AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.MAU_KE_HOACH_DIEU_TRI m WITH(UPDLOCK,HOLDLOCK) JOIN(SELECT MaMauKH FROM inserted UNION SELECT MaMauKH FROM deleted) x ON x.MaMauKH=m.MaMauKH WHERE m.TrangThai<>N''Nháp'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52115,N''Chỉ sửa bước của mẫu nháp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_DT_ThayThe ON dbo.DON_THUOC AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d JOIN inserted i ON i.MaDT=d.MaDT WHERE d.TrangThai<>N''Nháp'' AND EXISTS(SELECT i.MaDTThayThe EXCEPT SELECT d.MaDTThayThe))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52116,N''Đơn đã ký giữ nguyên nguồn thay thế.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=i.MaLS WHERE l.KhongKeThuoc=1 AND i.TrangThai IN(N''Nháp'',N''Đã xác nhận''))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52116,N''Lượt đã chọn không kê thuốc.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.DON_THUOC old ON old.MaDT=i.MaDTThayThe WHERE i.MaDT=old.MaDT OR i.MaLS<>old.MaLS OR i.MaBS<>old.MaBS)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52116,N''Đơn thay thế phải cùng lượt và bác sĩ, không tự trỏ chính nó.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaDT=i.MaDT WHERE i.MaDTThayThe IS NOT NULL AND (d.MaDT IS NULL OR d.TrangThai=N''Nháp'') AND'+NCHAR(13)+N''+NCHAR(10)+N' (EXISTS(SELECT 1 FROM dbo.HOA_DON h WHERE h.MaLS=i.MaLS) OR EXISTS(SELECT 1 FROM dbo.PHIEU_XUAT p WHERE p.MaLS=i.MaLS AND p.TrangThai=N''Đã ghi sổ'')))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52116,N''Không thay đơn của lượt đã lập hóa đơn hoặc đã xuất thuốc.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaDT=i.MaDT WHERE i.TrangThai=N''Ngừng áp dụng'' AND d.TrangThai<>N''Ngừng áp dụng'' AND'+NCHAR(13)+N''+NCHAR(10)+N' EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTDT=c.MaCTDT JOIN dbo.PHIEU_XUAT p ON p.MaPX=x.MaPX WHERE c.MaDT=i.MaDT AND p.TrangThai=N''Đã ghi sổ''))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52116,N''Đơn đã xuất thuốc giữ nguyên hiệu lực lịch sử.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_HD_Request ON dbo.HOA_DON AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaHD=i.MaHD WHERE d.TrangThai=N''Đã xác nhận'' AND EXISTS('+NCHAR(13)+N''+NCHAR(10)+N' SELECT i.PhienBanQuyTrinh,i.MaYeuCau,i.DauVanTayYeuCau EXCEPT SELECT d.PhienBanQuyTrinh,d.MaYeuCau,d.DauVanTayYeuCau))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52118,N''Hóa đơn đã xác nhận giữ nguyên khóa yêu cầu/phiên bản.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_KH_BaoVe ON dbo.KE_HOACH_DIEU_TRI AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaKHDT=d.MaKHDT WHERE d.TrangThai<>N''Nháp'' AND'+NCHAR(13)+N''+NCHAR(10)+N' (i.MaKHDT IS NULL OR i.TrangThai=N''Nháp'' OR EXISTS(SELECT i.MaLS,i.MaBS,i.NgayLap,i.NgayBatDau,i.NgayDuKienKetThuc,i.GhiChu,i.MaTTBNguon,i.MaMauKH,i.PhienBanMau'+NCHAR(13)+N''+NCHAR(10)+N' EXCEPT SELECT d.MaLS,d.MaBS,d.NgayLap,d.NgayBatDau,d.NgayDuKienKetThuc,d.GhiChu,d.MaTTBNguon,d.MaMauKH,d.PhienBanMau)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52113,N''Kế hoạch đã duyệt chỉ cập nhật trạng thái tiến độ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN dbo.TINH_TRANG_BENH t ON t.MaTTB=i.MaTTBNguon'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.MAU_KE_HOACH_DIEU_TRI m ON m.MaMauKH=i.MaMauKH WHERE'+NCHAR(13)+N''+NCHAR(10)+N' (i.MaTTBNguon IS NOT NULL AND(t.MaTTB IS NULL OR t.MaLS<>i.MaLS)) OR'+NCHAR(13)+N''+NCHAR(10)+N' (i.MaMauKH IS NOT NULL AND(m.MaDMTT<>t.MaDMTT OR t.MaDMTT IS NULL OR m.PhienBan<>i.PhienBanMau)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52113,N''Nguồn tình trạng và mẫu phải khớp lượt, danh mục và phiên bản.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaKHDT=i.MaKHDT JOIN dbo.MAU_KE_HOACH_DIEU_TRI m ON m.MaMauKH=i.MaMauKH'+NCHAR(13)+N''+NCHAR(10)+N' WHERE (d.MaKHDT IS NULL OR EXISTS(SELECT i.MaMauKH,i.PhienBanMau EXCEPT SELECT d.MaMauKH,d.PhienBanMau)) AND m.TrangThai<>N''Đã duyệt'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52113,N''Chỉ sao chép mẫu đã duyệt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_LS_BaoVe ON dbo.LICH_SU_KHAM_BENH AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaLS=d.MaLS WHERE d.TrangThai=N''Đã xác nhận'' AND'+NCHAR(13)+N''+NCHAR(10)+N' (i.MaLS IS NULL OR EXISTS(SELECT i.TrieuChung,i.ChanDoan,i.KeHoachXuLy,i.GhiChu,i.KhongKeThuoc,i.LyDoKhongKeThuoc'+NCHAR(13)+N''+NCHAR(10)+N' EXCEPT SELECT d.TrieuChung,d.ChanDoan,d.KeHoachXuLy,d.GhiChu,d.KhongKeThuoc,d.LyDoKhongKeThuoc)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52110,N''Nội dung lần khám đã ký được giữ nguyên; ghi bổ sung bằng nhật ký.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.KhongKeThuoc=1 AND EXISTS(SELECT 1 FROM dbo.DON_THUOC d WHERE d.MaLS=i.MaLS AND d.TrangThai IN(N''Nháp'',N''Đã xác nhận'')))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52110,N''Đã chọn không kê thuốc thì không có đơn nháp hoặc đơn hiệu lực.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_MauKH_BaoVe ON dbo.MAU_KE_HOACH_DIEU_TRI AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaMauKH=d.MaMauKH WHERE d.TrangThai<>N''Nháp'' AND'+NCHAR(13)+N''+NCHAR(10)+N' (i.MaMauKH IS NULL OR i.TrangThai=N''Nháp'' OR EXISTS(SELECT i.MaDMTT,i.MucDo,i.TenMau,i.PhienBan,i.MaBSDuyet,i.NgayDuyet EXCEPT SELECT d.MaDMTT,d.MucDo,d.TenMau,d.PhienBan,d.MaBSDuyet,d.NgayDuyet)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52115,N''Mẫu đã duyệt giữ nguyên nội dung; tạo mã/phiên bản mới.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã duyệt'' AND'+NCHAR(13)+N''+NCHAR(10)+N' (NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_MAU_KE_HOACH c WHERE c.MaMauKH=i.MaMauKH) OR'+NCHAR(13)+N''+NCHAR(10)+N' NOT EXISTS(SELECT 1 FROM dbo.NHAN_VIEN n JOIN dbo.TAI_KHOAN t ON t.MaNV=n.MaNV WHERE n.MaNV=i.MaBSDuyet AND (n.MaChucVu=N''CV002'' OR EXISTS(SELECT 1 FROM dbo.VAI_TRO v WHERE v.MaVaiTro=t.MaVaiTro AND UPPER(LTRIM(RTRIM(v.TenVaiTro))) IN(N''ADMIN'',N''QUẢN TRỊ''))) AND n.TrangThai=N''Đang làm việc'' AND t.TrangThai=N''Đang hoạt động'')))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52115,N''Mẫu cần các bước và bác sĩ hoặc Admin đang hoạt động duyệt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_Phieu_BacSi ON dbo.PHIEU_KHAM_BENH AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPhieu=i.MaPhieu WHERE EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaPhieu=i.MaPhieu)'+NCHAR(13)+N''+NCHAR(10)+N' AND EXISTS(SELECT i.MaBS,i.MaPhong EXCEPT SELECT d.MaBS,d.MaPhong))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52112,N''Phiếu đã bắt đầu khám không thay bác sĩ hoặc phòng.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_TT_ThuDu ON dbo.THANH_TOAN AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @id nvarchar(50); SELECT @id=h.MaHD FROM dbo.HOA_DON h WITH(UPDLOCK,HOLDLOCK) JOIN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted) x ON x.MaHD=h.MaHD;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD WHERE h.PhienBanQuyTrinh=2 AND'+NCHAR(13)+N''+NCHAR(10)+N' (i.TrangThai<>N''Đã xác nhận'' OR i.LoaiGiaoDich<>N''Thu'' OR i.SoTien<>h.SoTienPhaiThu OR i.SoTienKhachDua IS NULL OR i.TienThua IS NULL))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52119,N''Quy trình 2 chỉ ghi một giao dịch Thu đủ có tiền đưa và tiền thối.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.HOA_DON h JOIN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted) x ON x.MaHD=h.MaHD WHERE h.PhienBanQuyTrinh=2 AND'+NCHAR(13)+N''+NCHAR(10)+N' (SELECT COUNT(*) FROM dbo.THANH_TOAN t WHERE t.MaHD=h.MaHD AND t.TrangThai=N''Đã xác nhận'' AND t.LoaiGiaoDich=N''Thu'')<>1)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52119,N''Hóa đơn quy trình 2 có đúng một lần Thu đủ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CW_TTB_BaoVe ON dbo.TINH_TRANG_BENH AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WITH(UPDLOCK,HOLDLOCK) JOIN(SELECT MaLS FROM inserted UNION SELECT MaLS FROM deleted) x ON x.MaLS=l.MaLS WHERE l.TrangThai=N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52111,N''Không sửa hoặc bổ sung tình trạng vào lượt đã ký.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_DT_XacNhan ON dbo.DON_THUOC'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaDT=d.MaDT WHERE d.TrangThai<>N''Nháp'' AND(i.MaDT IS NULL OR i.TrangThai=N''Nháp'' OR EXISTS(SELECT i.MaLS,i.MaBS,i.NgayKe,i.LyDoThayThe,i.GhiChu EXCEPT SELECT d.MaLS,d.MaBS,d.NgayKe,d.LyDoThayThe,d.GhiChu)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51013,N''Đơn đã xác nhận chỉ được đổi trạng thái nghiệp vụ; thay chỉ định bằng đơn mới.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã xác nhận'' AND NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c WHERE c.MaDT=i.MaDT))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51014,N''Không xác nhận đơn thuốc rỗng.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_DVTH_KhoaNguon ON dbo.DICH_VU_THUC_HIEN'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51015,N''Dịch vụ đã xác nhận không sửa hoặc xóa nguồn thu.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_KE_HOACH c ON c.MaCTKH=i.MaCTKH JOIN dbo.KE_HOACH_DIEU_TRI k ON k.MaKHDT=c.MaKHDT'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=i.MaLS JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=l.MaPhieu'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.LICH_SU_KHAM_BENH l0 ON l0.MaLS=k.MaLS JOIN dbo.PHIEU_KHAM_BENH p0 ON p0.MaPhieu=l0.MaPhieu'+NCHAR(13)+N''+NCHAR(10)+N' WHERE c.MaDV<>i.MaDV OR p.MaHS<>p0.MaHS OR c.TrangThai=N''Hủy'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51016,N''Dịch vụ phải khớp kế hoạch và cùng hồ sơ bệnh án; không thực hiện dòng đã hủy.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_HD_ChotHoanTat ON dbo.HOA_DON'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaHD=d.MaHD WHERE d.TaoKhiHoanTat=1'+NCHAR(13)+N''+NCHAR(10)+N'  AND(i.MaHD IS NULL OR EXISTS(SELECT i.MaLS,i.MaNV,i.NgayLap,i.GiamGia,i.TaoKhiHoanTat EXCEPT SELECT d.MaLS,d.MaNV,d.NgayLap,d.GiamGia,d.TaoKhiHoanTat)'+NCHAR(13)+N''+NCHAR(10)+N'   OR i.TrangThai=N''Hủy''))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52234,N''Hóa đơn hoàn tất giữ nguyên danh tính, nguồn và giảm giá.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON other ON other.MaLS=i.MaLS AND other.MaHD<>i.MaHD'+NCHAR(13)+N''+NCHAR(10)+N'  WHERE i.TaoKhiHoanTat=1 OR other.TaoKhiHoanTat=1)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52235,N''Lượt hoàn tất chỉ có một hóa đơn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã xác nhận'''+NCHAR(13)+N''+NCHAR(10)+N'  AND EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD AND c.MaCTDT IS NOT NULL))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52236,N''Xuất đủ thuốc và đối chiếu hóa đơn trước xác nhận thu.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted old ON old.MaHD=i.MaHD'+NCHAR(13)+N''+NCHAR(10)+N'  WHERE i.TaoKhiHoanTat=1 AND COALESCE(old.TaoKhiHoanTat,0)=0 AND'+NCHAR(13)+N''+NCHAR(10)+N'  (i.TrangThai<>N''Nháp'' OR i.PhienBanQuyTrinh<>1 OR i.GiamGia<>0'+NCHAR(13)+N''+NCHAR(10)+N'   OR NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD)'+NCHAR(13)+N''+NCHAR(10)+N'   OR EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaLS=i.MaLS AND l.TrangThai<>N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N'   OR EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD AND c.MaCTPX IS NOT NULL)'+NCHAR(13)+N''+NCHAR(10)+N'   OR EXISTS(SELECT 1 FROM dbo.DICH_VU_THUC_HIEN s WHERE s.MaLS=i.MaLS AND s.TrangThai=N''Đã xác nhận'''+NCHAR(13)+N''+NCHAR(10)+N'     AND NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD AND c.MaDVThucHien=s.MaDVThucHien))'+NCHAR(13)+N''+NCHAR(10)+N'   OR EXISTS(SELECT 1 FROM dbo.DON_THUOC r JOIN dbo.CHI_TIET_DON_THUOC d ON d.MaDT=r.MaDT'+NCHAR(13)+N''+NCHAR(10)+N'     WHERE r.MaLS=i.MaLS AND r.TrangThai=N''Đã xác nhận'' AND NOT EXISTS('+NCHAR(13)+N''+NCHAR(10)+N'      SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD AND c.MaCTDT=d.MaCTDT))))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52237,N''Hóa đơn hoàn tất phải chốt đủ dịch vụ và thuốc đã ký của lượt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_HD_XacNhan ON dbo.HOA_DON'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51004,N''Hóa đơn đã xác nhận giữ nguyên; không sửa, hủy hay xóa.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã xác nhận'' AND NOT EXISTS(SELECT 1 FROM deleted d WHERE d.MaHD=i.MaHD))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51005,N''Tạo hóa đơn nháp và chi tiết trước khi xác nhận.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Hủy'' AND EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51006,N''Gỡ chi tiết hóa đơn nháp trước khi hủy để giải phóng nguồn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TongTien<>COALESCE((SELECT SUM(c.ThanhTien) FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51007,N''TongTien phải bằng tổng ThanhTien chi tiết; không nhập tổng độc lập.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã xác nhận'' AND'+NCHAR(13)+N''+NCHAR(10)+N' (NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD)'+NCHAR(13)+N''+NCHAR(10)+N' OR EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaLS=i.MaLS AND(l.TrangThai<>N''Đã xác nhận'' OR i.NgayLap<l.ThoiGianKham))'+NCHAR(13)+N''+NCHAR(10)+N' OR EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=c.MaDVThucHien'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=c.MaCTPX'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.PHIEU_XUAT p ON p.MaPX=x.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' WHERE c.MaHD=i.MaHD AND((c.MaDVThucHien IS NOT NULL AND(s.TrangThai<>N''Đã xác nhận'' OR s.MaLS<>i.MaLS OR s.ThanhTien<>c.ThanhTien OR s.ThoiGianThucHien>i.NgayXacNhan))'+NCHAR(13)+N''+NCHAR(10)+N' OR(c.MaCTPX IS NOT NULL AND(p.TrangThai<>N''Đã ghi sổ'' OR p.MaLS<>i.MaLS OR x.MaCTDT IS NULL OR CAST(ROUND(x.SoLuong*c.DonGia,2) AS DECIMAL(18,2))<>c.ThanhTien OR p.NgayXuat>i.NgayXacNhan))))))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51008,N''Không xác nhận hóa đơn rỗng, nguồn sai, thời gian sai hoặc thành tiền chưa khớp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_HH_KhoaDonVi ON dbo.HANG_HOA'+NCHAR(13)+N''+NCHAR(10)+N'AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaHH=i.MaHH WHERE i.DonViTinh<>d.DonViTinh AND'+NCHAR(13)+N''+NCHAR(10)+N' (EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_NHAP c WHERE c.MaHH=i.MaHH) OR EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_XUAT c WHERE c.MaHH=i.MaHH) OR EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c JOIN dbo.THUOC t ON t.MaThuoc=c.MaThuoc WHERE t.MaHH=i.MaHH)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51031,N''Không đổi đơn vị cơ sở sau khi đã kê/nhập/xuất.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_HS_KhoaBenhNhanNguon ON dbo.HO_SO_BENH_AN'+NCHAR(13)+N''+NCHAR(10)+N'AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaHS=i.MaHS WHERE i.MaBN<>d.MaBN AND EXISTS(SELECT 1 FROM dbo.PHIEU_KHAM_BENH p WHERE p.MaHS=i.MaHS))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51040,N''Hồ sơ đã tiếp nhận không chuyển sang bệnh nhân khác; giữ nguyên nguồn bệnh án và hóa đơn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_KHDT_Tong ON dbo.KE_HOACH_DIEU_TRI'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TongTienDuKien<>COALESCE((SELECT SUM(c.ThanhTienDuKien) FROM dbo.CHI_TIET_KE_HOACH c WHERE c.MaKHDT=i.MaKHDT AND c.TrangThai<>N''Hủy''),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51017,N''Tổng dự kiến phải bằng chi tiết chưa hủy.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N''+NCHAR(13)+N''+NCHAR(10)+N'    CREATE   TRIGGER dbo.TR_LLV_KhoaKyDaChot ON dbo.LICH_LAM_VIEC'+NCHAR(13)+N''+NCHAR(10)+N'    AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'    BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'      SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'      IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaLLV=i.MaLLV'+NCHAR(13)+N''+NCHAR(10)+N'        JOIN dbo.BANG_LUONG b ON b.MaNV=i.MaNV AND i.NgayLam BETWEEN b.TuNgay AND b.DenNgay'+NCHAR(13)+N''+NCHAR(10)+N'        WHERE b.TrangThai=N''Đã chốt'' AND (i.MaNV<>d.MaNV OR i.NgayLam<>d.NgayLam))'+NCHAR(13)+N''+NCHAR(10)+N'        THROW 51113,N''Không chuyển lịch từ kỳ đang mở vào kỳ lương đã chốt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'      IF EXISTS ('+NCHAR(13)+N''+NCHAR(10)+N'        SELECT 1 FROM inserted i'+NCHAR(13)+N''+NCHAR(10)+N'        JOIN dbo.BANG_LUONG b ON b.MaNV=i.MaNV AND i.NgayLam BETWEEN b.TuNgay AND b.DenNgay'+NCHAR(13)+N''+NCHAR(10)+N'        LEFT JOIN deleted d ON d.MaLLV=i.MaLLV'+NCHAR(13)+N''+NCHAR(10)+N'        WHERE b.TrangThai=N''Đã chốt'' AND d.MaLLV IS NULL)'+NCHAR(13)+N''+NCHAR(10)+N'        THROW 51113,N''Không thêm lịch vào kỳ lương đã chốt.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'      IF EXISTS('+NCHAR(13)+N''+NCHAR(10)+N'        SELECT 1 FROM deleted d'+NCHAR(13)+N''+NCHAR(10)+N'        JOIN dbo.BANG_LUONG b ON b.MaNV=d.MaNV AND d.NgayLam BETWEEN b.TuNgay AND b.DenNgay'+NCHAR(13)+N''+NCHAR(10)+N'        LEFT JOIN inserted i ON i.MaLLV=d.MaLLV'+NCHAR(13)+N''+NCHAR(10)+N'        WHERE b.TrangThai=N''Đã chốt'' AND ('+NCHAR(13)+N''+NCHAR(10)+N'          i.MaLLV IS NULL OR'+NCHAR(13)+N''+NCHAR(10)+N'          ISNULL(i.MaNV,N'''')<>ISNULL(d.MaNV,N'''') OR'+NCHAR(13)+N''+NCHAR(10)+N'          i.NgayLam<>d.NgayLam OR i.MaCa<>d.MaCa OR'+NCHAR(13)+N''+NCHAR(10)+N'          ISNULL(i.TrangThai,N'''')<>ISNULL(d.TrangThai,N'''') OR'+NCHAR(13)+N''+NCHAR(10)+N'          ISNULL(i.TrangThaiHienDien,N'''')<>ISNULL(d.TrangThaiHienDien,N'''') OR'+NCHAR(13)+N''+NCHAR(10)+N'          ISNULL(i.GioVao,CONVERT(DATETIME2(0),''19000101''))<>ISNULL(d.GioVao,CONVERT(DATETIME2(0),''19000101'')) OR'+NCHAR(13)+N''+NCHAR(10)+N'          ISNULL(i.GioRa,CONVERT(DATETIME2(0),''19000101''))<>ISNULL(d.GioRa,CONVERT(DATETIME2(0),''19000101''))'+NCHAR(13)+N''+NCHAR(10)+N'        )) THROW 51113,N''Lịch chấm công thuộc kỳ lương đã chốt, không thể sửa.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'    END'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_LO_KhoaNguon ON dbo.LO_HANG_HOA'+NCHAR(13)+N''+NCHAR(10)+N'AFTER UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted d WHERE EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_NHAP c JOIN dbo.PHIEU_NHAP p ON p.MaPN=c.MaPN WHERE c.MaLo=d.MaLo AND p.TrangThai=N''Đã ghi sổ'') OR EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_XUAT c JOIN dbo.PHIEU_XUAT p ON p.MaPX=c.MaPX WHERE c.MaLo=d.MaLo AND p.TrangThai=N''Đã ghi sổ''))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51030,N''Lô đã có chứng từ ghi sổ giữ nguyên thuộc tính nguồn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_LS_LienKet ON dbo.LICH_SU_KHAM_BENH'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaLS=i.MaLS WHERE d.TrangThai=N''Đã xác nhận'' AND EXISTS(SELECT i.MaPhieu,i.MaBS,i.MaPhong,i.ThoiGianKham,i.TrangThai,i.NgayXacNhan EXCEPT SELECT d.MaPhieu,d.MaBS,d.MaPhong,d.ThoiGianKham,d.TrangThai,d.NgayXacNhan))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51035,N''Lần khám đã xác nhận giữ nguyên liên kết và thời gian nguồn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=i.MaPhieu WHERE i.ThoiGianKham<p.ThoiGianTiepNhan OR i.MaPhong<>p.MaPhong OR(p.MaBS IS NOT NULL AND i.MaBS<>p.MaBS))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51036,N''Lần khám phải khớp phiếu tiếp nhận và không trước giờ tiếp nhận.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N''+NCHAR(13)+N''+NCHAR(10)+N'    CREATE   TRIGGER dbo.TR_NKCC_KhongSua ON dbo.NHAT_KY_DUYET_CHAM_CONG'+NCHAR(13)+N''+NCHAR(10)+N'    AFTER UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'    BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'      SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'      THROW 51111,N''Nhật ký đối soát chỉ được thêm, không được sửa hay xóa.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'    END'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PHIEU_LienKet ON dbo.PHIEU_KHAM_BENH'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HO_SO_BENH_AN h ON h.MaHS=i.MaHS JOIN dbo.LICH_KHAM l ON l.MaLich=i.MaLich WHERE l.MaBN<>h.MaBN OR l.MaPhong<>i.MaPhong OR(i.MaBS IS NOT NULL AND l.MaBS<>i.MaBS))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51033,N''Phiếu tiếp nhận có lịch phải khớp bệnh nhân, phòng và bác sĩ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPhieu=i.MaPhieu WHERE EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaPhieu=i.MaPhieu) AND EXISTS(SELECT i.MaHS,i.MaLich EXCEPT SELECT d.MaHS,d.MaLich))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51034,N''Phiếu đã phát sinh lần khám không đổi hồ sơ/lịch nguồn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PN_GhiSo ON dbo.PHIEU_NHAP'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @Lock NVARCHAR(50);'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=h.MaHH FROM dbo.HANG_HOA h WITH(UPDLOCK,HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.CHI_TIET_PHIEU_NHAP c ON c.MaHH=h.MaHH JOIN inserted i ON i.MaPN=c.MaPN;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã ghi sổ'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51020,N''Phiếu nhập đã ghi sổ giữ nguyên.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_NHAP c ON c.MaPN=i.MaPN JOIN dbo.HOA_DON_NHAP h ON h.MaHDN=i.MaHDN JOIN dbo.LO_HANG_HOA l ON l.MaLo=c.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE l.MaHH<>c.MaHH OR l.MaKho<>i.MaKho OR l.MaNCC<>h.MaNCC)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51019,N''Nguồn phiếu nhập phải khớp hàng hóa, kho và nhà cung cấp của các lô chi tiết.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TongTien<>COALESCE((SELECT SUM(c.ThanhTien) FROM dbo.CHI_TIET_PHIEU_NHAP c WHERE c.MaPN=i.MaPN),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51021,N''Tổng nhập phải bằng chi tiết.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã ghi sổ'' AND NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_NHAP c WHERE c.MaPN=i.MaPN))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51022,N''Không ghi sổ phiếu nhập rỗng.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PX_GhiSoDuDon ON dbo.PHIEU_XUAT'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @Lock NVARCHAR(50);'+NCHAR(13)+N''+NCHAR(10)+N' -- Khóa mặt hàng dùng chung cho nhập/xuất để tránh hai quầy cùng dùng tồn.'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=h.MaHH FROM dbo.HANG_HOA h WITH(UPDLOCK,HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.CHI_TIET_PHIEU_XUAT c ON c.MaHH=h.MaHH JOIN inserted i ON i.MaPX=c.MaPX;'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=d.MaDT FROM dbo.DON_THUOC d WITH(UPDLOCK,HOLDLOCK) JOIN dbo.CHI_TIET_DON_THUOC ct ON ct.MaDT=d.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTDT=ct.MaCTDT JOIN inserted i ON i.MaPX=x.MaPX;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã ghi sổ'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51025,N''Phiếu xuất đã ghi sổ giữ nguyên; không giảm lượng hoặc cấp lại.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=x.MaCTDT LEFT JOIN dbo.DON_THUOC d ON d.MaDT=c.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.THUOC t ON t.MaThuoc=c.MaThuoc LEFT JOIN dbo.LO_HANG_HOA l ON l.MaLo=x.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE(i.MaLS IS NOT NULL AND(x.MaCTDT IS NULL OR i.MaLS<>d.MaLS OR x.MaHH<>t.MaHH OR x.MaLo IS NULL))'+NCHAR(13)+N''+NCHAR(10)+N' OR(i.MaLS IS NULL AND x.MaCTDT IS NOT NULL) OR(x.MaLo IS NOT NULL AND(l.MaHH<>x.MaHH OR l.MaKho<>i.MaKho)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51024,N''Nguồn phiếu xuất phải khớp đơn thuốc, bệnh nhân, lô và kho của mọi chi tiết.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã ghi sổ'' AND NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_XUAT c WHERE c.MaPX=i.MaPX))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51026,N''Không ghi sổ phiếu xuất rỗng.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=x.MaCTDT LEFT JOIN dbo.DON_THUOC d ON d.MaDT=c.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.LO_HANG_HOA l ON l.MaLo=x.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE i.TrangThai=N''Đã ghi sổ'' AND((x.MaCTDT IS NOT NULL AND(d.TrangThai<>N''Đã xác nhận'' OR d.NgayKe>i.NgayXuat))'+NCHAR(13)+N''+NCHAR(10)+N' OR (x.MaLo IS NOT NULL AND(l.TrangThai<>N''Còn sử dụng'' OR l.NgayNhap>i.NgayXuat OR(l.HanSuDung IS NOT NULL AND l.HanSuDung<CAST(i.NgayXuat AS DATE))))))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51027,N''Đơn chưa xác nhận/ngừng áp dụng hoặc lô không hợp lệ, hết hạn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' -- Mọi dòng của các đơn đang cấp phải đã xuất đủ trong cùng transaction.'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c WHERE c.MaDT IN'+NCHAR(13)+N''+NCHAR(10)+N' (SELECT ct.MaDT FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX JOIN dbo.CHI_TIET_DON_THUOC ct ON ct.MaCTDT=x.MaCTDT WHERE i.TrangThai=N''Đã ghi sổ'')'+NCHAR(13)+N''+NCHAR(10)+N' AND c.SoLuong<>COALESCE((SELECT SUM(x.SoLuong) FROM dbo.CHI_TIET_PHIEU_XUAT x JOIN dbo.PHIEU_XUAT p ON p.MaPX=x.MaPX WHERE x.MaCTDT=c.MaCTDT AND p.TrangThai=N''Đã ghi sổ''),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51028,N''Phải cấp đủ toàn bộ đơn trong một lần xác nhận; không cấp một phần hoặc cấp lại.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX WHERE i.TrangThai=N''Đã ghi sổ'''+N' AND'+NCHAR(13)+N''+NCHAR(10)+N' COALESCE((SELECT SUM(n.SoLuong) FROM dbo.CHI_TIET_PHIEU_NHAP n JOIN dbo.PHIEU_NHAP p ON p.MaPN=n.MaPN WHERE p.TrangThai=N''Đã ghi sổ'' AND p.MaKho=i.MaKho AND n.MaHH=x.MaHH AND(n.MaLo=x.MaLo OR(n.MaLo IS NULL AND x.MaLo IS NULL))),0)'+NCHAR(13)+N''+NCHAR(10)+N' < COALESCE((SELECT SUM(e.SoLuong) FROM dbo.CHI_TIET_PHIEU_XUAT e JOIN dbo.PHIEU_XUAT p ON p.MaPX=e.MaPX WHERE p.TrangThai=N''Đã ghi sổ'' AND p.MaKho=i.MaKho AND e.MaHH=x.MaHH AND(e.MaLo=x.MaLo OR(e.MaLo IS NULL AND x.MaLo IS NULL))),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51029,N''Không đủ tồn kho/lô; rollback toàn bộ lần cấp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_RHM_DichVu_ChiTrongKham ON dbo.DICH_VU_THUC_HIEN AFTER INSERT,UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=i.MaLS WHERE l.TrangThai<>N''Nháp'') THROW 52234,N''Không thêm/sửa dịch vụ sau khi hoàn tất khám.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
