 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_THUOC_KhoaHangHoa ON dbo.THUOC'+NCHAR(13)+N''+NCHAR(10)+N'AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaThuoc=i.MaThuoc WHERE i.MaHH<>d.MaHH AND EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c WHERE c.MaThuoc=i.MaThuoc))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51032,N''Thuốc đã kê đơn không đổi hàng hóa nguồn; DonGiaBan hiện hành vẫn được cập nhật.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_TT_KiemTraSoDu ON dbo.THANH_TOAN'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @Lock NVARCHAR(50);'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=h.MaHD FROM dbo.HOA_DON h WITH(UPDLOCK,HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' WHERE h.MaHD IN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted);'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51009,N''Giao dịch đã xác nhận không sửa/xóa; lập giao dịch điều chỉnh mới.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD WHERE i.TrangThai=N''Đã xác nhận'' AND(h.TrangThai<>N''Đã xác nhận'' OR i.NgayThanhToan<h.NgayXacNhan))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51010,N''Chỉ thu/hoàn sau khi hóa đơn đã xác nhận.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.HOA_DON h JOIN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted) z ON z.MaHD=h.MaHD'+NCHAR(13)+N''+NCHAR(10)+N' OUTER APPLY(SELECT SUM(CASE WHEN t.LoaiGiaoDich=N''Thu'' THEN t.SoTien ELSE -t.SoTien END) ThuRong FROM dbo.THANH_TOAN t WHERE t.MaHD=h.MaHD AND t.TrangThai=N''Đã xác nhận'') a'+NCHAR(13)+N''+NCHAR(10)+N' WHERE COALESCE(a.ThuRong,0)<0 OR COALESCE(a.ThuRong,0)>h.SoTienPhaiThu)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51011,N''Thu vượt tiền phải trả hoặc hoàn vượt tiền đang giữ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
