 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.HospitalWorkflow.Version'',@value=3;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.MaintenanceSerial.Version'',@value=1;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.PrescriptionFlow.Version'',@value=1;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.RelatedServices.Version'',@value=1;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.SimpleConditions.Version'',@value=1;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.SqlV9.Version'',@value=9;'; EXEC sys.sp_executesql @RhmSnapshotSql;
