IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.KE_HOACH_DIEU_TRI'') AND name=N''IX_CW_KH_Mau'' AND is_disabled=0) THROW 52102,N''Thiếu index IX_CW_KH_Mau.'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.DON_THUOC'') AND name=N''IX_CW_DT_ThayThe'' AND is_disabled=0) THROW 52102,N''Thiếu index IX_CW_DT_ThayThe.'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.MAU_KE_HOACH_DIEU_TRI'') AND name=N''IX_CW_Mau_TinhTrang'' AND is_disabled=0) THROW 52102,N''Thiếu index IX_CW_Mau_TinhTrang.'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.CAU_HINH_THUOC_KE_DON'') AND name=N''IX_CW_CauHinh_Nhom'' AND is_disabled=0) THROW 52102,N''Thiếu index IX_CW_CauHinh_Nhom.'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.BAN_GIAO_THUOC'') AND name=N''IX_CW_BanGiao_HD'' AND is_disabled=0) THROW 52102,N''Thiếu index IX_CW_BanGiao_HD.'',1;IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name LIKE N''FK[_]CW[_]%'' AND(is_disabled=1 OR is_not_trusted=1)) THROW 52102,N''FK mới chưa được kiểm chứng.'',1;
SELECT N''ClinicalWorkflow v2'' AS SchemaVersion,COUNT(*) AS TableCount FROM sys.tables WHERE is_ms_shipped=0;
SELECT MaHD,MaLS,SoTienPhaiThu,DaThuRong,ConPhaiTra FROM dbo.VW_HOA_DON_THANH_TOAN WHERE ConPhaiTra<>0;IF COL_LENGTH(N''dbo.HOA_DON'',N''TaoKhiHoanTat'') IS NULL OR COL_LENGTH(N''dbo.CHI_TIET_HOA_DON'',N''MaCTDT'') IS NULL THROW 52272,N''Thiếu cột hóa đơn hoàn tất; chạy toàn bộ QLBenhVienRangHamMat.sql.'',1;
IF COL_LENGTH(N''dbo.TINH_TRANG_BENH'',N''MucDo'') IS NOT NULL OR COL_LENGTH(N''dbo.TINH_TRANG_BENH'',N''ViTriRang'') IS NOT NULL THROW 52272,N''Schema tình trạng không khớp ứng dụng.'',1;
IF OBJECT_ID(N''dbo.DICH_VU_TINH_TRANG'') IS NULL OR OBJECT_ID(N''dbo.TR_RHM_DichVu_ChiTrongKham'') IS NULL OR OBJECT_ID(N''dbo.TR_HD_ChotHoanTat'') IS NULL THROW 52272,N''Thiếu liên kết hoặc bảo vệ hoàn tất.'',1;
IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''RHM.HospitalWorkflow.Version'' AND TRY_CONVERT(int,value)=3) THROW 52272,N''Chưa đồng bộ HospitalWorkflow3.'',1;
IF (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped=0) NOT IN(53,60) THROW 52272,N''Số bảng không đúng nền 53 hoặc bản hợp nhất 60.'',1;
IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM sys.triggers WHERE parent_class=1 AND is_disabled=1) THROW 52272,N''Ràng buộc hoặc trigger chưa hợp lệ.'',1;
END;';

 IF (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped=0) NOT IN(53,60) THROW 52272,N'Số bảng khác nền 53 hoặc bản hợp nhất 60 đã hỗ trợ.',1;
 IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM sys.triggers WHERE parent_class=1 AND is_disabled=1)
 THROW 52272,N'Có ràng buộc hoặc trigger bị tắt/chưa kiểm chứng.',1;
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.HospitalWorkflow.Version')
 EXEC sys.sp_updateextendedproperty @name=N'RHM.HospitalWorkflow.Version',@value=3;
 ELSE EXEC sys.sp_addextendedproperty @name=N'RHM.HospitalWorkflow.Version',@value=3;
 EXEC sys.sp_set_session_context @key=N'RHM.MaTK',@value=@hospitalPreviousActor;
 COMMIT;
 EXEC sys.sp_set_session_context @key=N'RHM.HospitalWorkflow.Completed',@value=1;
 PRINT N'Hoàn tất khởi tạo/đồng bộ HospitalWorkflow v3; dữ liệu người dùng và lịch sử tài chính được giữ nguyên.';
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK;
 EXEC sys.sp_set_session_context @key=N'RHM.MaTK',@value=@hospitalPreviousActor;
 THROW;
END CATCH;
GO
-- Giai đoạn4: kê thuốc trong khám, nhóm thuốc độc lập mẫu.
DECLARE @rxPreviousActor sql_variant=SESSION_CONTEXT(N'RHM.MaTK');
DECLARE @rxCatalogActor nvarchar(50)=(SELECT TOP(1) t.MaTK FROM dbo.TAI_KHOAN t JOIN dbo.NHAN_VIEN n ON n.MaNV=t.MaNV JOIN dbo.VAI_TRO v ON v.MaVaiTro=t.MaVaiTro WHERE t.TrangThai=N'Đang hoạt động' AND n.TrangThai=N'Đang làm việc' AND UPPER(LTRIM(RTRIM(v.TenVaiTro))) IN(N'ADMIN',N'QUẢN TRỊ') ORDER BY t.MaTK);
-- RHM medicinal catalog, reference date 29/10/2026.
-- Integrate after NHOM_THUOC_KE_DON creation in the canonical database script.
-- 52 genuine products; 40 published reference prices; 12 explicitly unset prices (0).
-- No doses, prescribing guidance, approval records, people, lots, balances or transactions.
-- Running this fragment repeatedly preserves existing prices and changed catalog fields.
SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRANSACTION;
 IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.HospitalWorkflow.Completed')),0)<>1 THROW 52324,N'Phải hoàn tất đồng bộ HospitalWorkflow trước danh mục thuốc.',1;
 IF @rxCatalogActor IS NULL THROW 52324,N'Cần tài khoản quản trị hoạt động để ghi nhận đồng bộ nhóm thuốc.',1;
 EXEC sys.sp_set_session_context @key=N'RHM.MaTK',@value=@rxCatalogActor;
 IF OBJECT_ID(N'dbo.NHOM_THUOC_KE_DON',N'U') IS NULL OR OBJECT_ID(N'dbo.THUOC',N'U') IS NULL
  THROW 52320,N'Cần tạo bảng THUOC và NHOM_THUOC_KE_DON trước danh mục thuốc.',1;
 IF COL_LENGTH(N'dbo.THUOC',N'MaNhomThuoc') IS NULL
  EXEC sys.sp_executesql N'ALTER TABLE dbo.THUOC ADD MaNhomThuoc nvarchar(50) NULL;';
 IF NOT EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.THUOC') AND name=N'MaNhomThuoc' AND TYPE_NAME(user_type_id)=N'nvarchar' AND max_length=100 AND is_nullable=1)
  THROW 52320,N'Kiểu cột THUOC.MaNhomThuoc không đúng hợp đồng.',1;
 IF NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_RX_Thuoc_Nhom' AND parent_object_id=OBJECT_ID(N'dbo.THUOC'))
  EXEC sys.sp_executesql N'ALTER TABLE dbo.THUOC WITH CHECK ADD CONSTRAINT FK_RX_Thuoc_Nhom FOREIGN KEY(MaNhomThuoc) REFERENCES dbo.NHOM_THUOC_KE_DON(MaNhomThuoc);';
 IF NOT EXISTS(
  SELECT 1 FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id=fk.object_id
  WHERE fk.name=N'FK_RX_Thuoc_Nhom' AND fk.parent_object_id=OBJECT_ID(N'dbo.THUOC')
   AND fk.referenced_object_id=OBJECT_ID(N'dbo.NHOM_THUOC_KE_DON')
   AND COL_NAME(fkc.parent_object_id,fkc.parent_column_id)=N'MaNhomThuoc'
   AND COL_NAME(fkc.referenced_object_id,fkc.referenced_column_id)=N'MaNhomThuoc')
  THROW 52320,N'Khóa ngoại FK_RX_Thuoc_Nhom không đúng cấu trúc yêu cầu.',1;
 EXEC sys.sp_executesql N'ALTER TABLE dbo.THUOC WITH CHECK CHECK CONSTRAINT FK_RX_Thuoc_Nhom;';
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.THUOC') AND name=N'IX_RX_Thuoc_Nhom')
  EXEC sys.sp_executesql N'CREATE INDEX IX_RX_Thuoc_Nhom ON dbo.THUOC(MaNhomThuoc);';
 -- Dynamic batch permits referencing a column added in this same transaction.
 EXEC sys.sp_executesql N'DECLARE @Groups TABLE (MaNhomThuoc nvarchar(50) PRIMARY KEY, TenNhom nvarchar(255), MoTa nvarchar(max));
INSERT @Groups VALUES
(N''RHM_GIAM_DAU'',N''Giảm đau - hạ sốt'',N''Paracetamol; phân nhóm danh mục, không phải chỉ định.''),
