 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'PhuCapCoDinh') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.CHINH_SACH_LUONG ADD [PhuCapCoDinh] decimal(18,2) NOT NULL CONSTRAINT DF_CSL_PhuCap DEFAULT(0);';
 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'TyLeBHXH') IS NULL
