(N''PK_CHI_TIET_LUONG'',N''PK''),
(N''CK_CTL_1'',N''C''),
(N''CK_CTL_2'',N''C''),
(N''CK_CTL_3'',N''C''),
(N''PK_PHU_TA_DICH_VU'',N''PK''),
(N''UQ_PHU_TA_DV'',N''UQ''),
(N''CK_PHU_TA_DV_TT'',N''C''),
(N''PK_CHI_TIET_HOA_HONG_LUONG'',N''PK''),
(N''CK_CTHH_1'',N''C''),
(N''CK_CTHH_2'',N''C''),
(N''UQ_CTHH_Luong_DichVu'',N''UQ''),
(N''PK_LAM_THEM_GIO'',N''PK''),
(N''CK_LTG_1'',N''C''),
(N''CK_LTG_2'',N''C''),
(N''CK_LTG_3'',N''C''),
(N''PK_NHAT_KY_DUYET_CHAM_CONG'',N''PK'')) required(N,T) WHERE OBJECT_ID(N''dbo.''+required.N,required.T) IS NULL)
  THROW 52335,N''Thiếu PK/UNIQUE/CHECK/DEFAULT của các bảng V9.'',1;
 IF EXISTS(SELECT 1 FROM @cols e LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N''dbo.''+e.T) AND c.name=e.C
  LEFT JOIN sys.types t ON t.user_type_id=c.user_type_id WHERE c.column_id IS NULL OR t.name<>e.Ty OR c.max_length<>e.L OR c.is_nullable<>e.N
  OR (e.Ty=N''decimal'' AND(c.precision<>e.P OR c.scale<>e.S)) OR(e.Ty=N''datetime2'' AND c.scale<>e.S))
  THROW 52335,N''Thiếu hoặc sai kiểu cột lịch khám/chấm công/lương V9.'',1;
 IF (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped=0)<>60
  THROW 52335,N''Schema hợp nhất phải có đủ 60 bảng.'',1;
 IF NOT EXISTS(SELECT 1 FROM sys.computed_columns WHERE object_id=OBJECT_ID(N''dbo.BANG_LUONG'') AND name=N''LuongTheoCa'' AND is_persisted=1 AND definition LIKE N''%PhienBanTinhLuong%'' AND definition LIKE N''%LuongTheoCaTruocDongBo%'' AND definition LIKE N''%CongThucTe%'')
 OR NOT EXISTS(SELECT 1 FROM sys.computed_columns WHERE object_id=OBJECT_ID(N''dbo.BANG_LUONG'') AND name=N''TongLuong'' AND is_persisted=1 AND definition LIKE N''%TongLuongTruocDongBo%'' AND definition LIKE N''%TienBaoHiem%'')
  THROW 52335,N''Công thức lương không giữ bản tiền cũ hoặc chưa dùng V9.'',1;
 IF EXISTS(SELECT 1 FROM (VALUES
 (N''TR_BL_ChotLuong'',N''TR''),(N''TR_CTL_KhoaTheoBangLuong'',N''TR''),(N''TR_CTHH_KhoaTheoBangLuong'',N''TR''),
 (N''TR_NKCC_KhongSua'',N''TR''),(N''TR_CC_KhoaKyDaChot'',N''TR''),(N''TR_LLV_KhoaKyDaChot'',N''TR''),
 (N''RHM_TinhLuongKy'',N''P''),(N''RHM_ChotLuongNhanVien'',N''P''),(N''VW_CONG_CHUAN_BANG_LUONG'',N''V''),(N''VW_DICH_VU_DU_HOA_HONG'',N''V''),
 (N''CK_BL_PhienBan'',N''C''),(N''CK_BANG_LUONG_1'',N''C''),(N''CK_BANG_LUONG_2'',N''C''),(N''CK_BANG_LUONG_3'',N''C''),(N''CK_BANG_LUONG_4'',N''C''),(N''CK_BANG_LUONG_5'',N''C''),
 (N''CK_CHINH_SACH_LUONG_6'',N''C''),(N''CK_CHINH_SACH_LUONG_7'',N''C''),(N''CK_LICH_KHAM_MucDoNghiemTrong'',N''C''),(N''FK_LICH_KHAM_BacSiDuBi'',N''F''),
 (N''FK_BL_NguoiChot'',N''F''),(N''FK_CC_MaLLV'',N''F''),(N''FK_CC_NguoiDoiSoat'',N''F''),(N''FK_CTL_BangLuong'',N''F''),(N''FK_CTL_NguoiDuyet'',N''F''),
 (N''FK_PTDV_DVTH'',N''F''),(N''FK_PTDV_NV'',N''F''),(N''FK_CTHH_BL'',N''F''),(N''FK_CTHH_CTHD'',N''F''),(N''FK_LTG_NV'',N''F''),(N''FK_LTG_NguoiDuyet'',N''F''),
 (N''FK_NKCC_Lich'',N''F''),(N''FK_NKCC_NhanVien'',N''F''),(N''FK_NKCC_NguoiDuyet'',N''F''),(N''UQ_BANG_LUONG_NhanVien_Ky'',N''UQ'')) o(N,T)
 WHERE OBJECT_ID(N''dbo.''+o.N,o.T) IS NULL)
  THROW 52335,N''Thiếu đối tượng/ràng buộc SQL V9.'',1;
 IF EXISTS(SELECT 1 FROM (VALUES(N''NGAY_NGHI_LE'',N''IX_NNL_Ngay''),(N''CHI_TIET_LUONG'',N''IX_CTL_BangLuong''),(N''CHI_TIET_HOA_HONG_LUONG'',N''IX_CTHH_BangLuong''),(N''LAM_THEM_GIO'',N''IX_LTG_NV_Ngay''),(N''NHAT_KY_DUYET_CHAM_CONG'',N''IX_NKCC_Lich_Ngay'')) e(T,N)
  LEFT JOIN sys.indexes i ON i.object_id=OBJECT_ID(N''dbo.''+e.T) AND i.name=e.N WHERE i.index_id IS NULL OR i.is_disabled=1 OR i.is_hypothetical=1)
  THROW 52335,N''Thiếu hoặc tắt index SQL V9.'',1;
 IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1)
 OR EXISTS(SELECT 1 FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1)
 OR EXISTS(SELECT 1 FROM sys.triggers WHERE parent_class=1 AND is_disabled=1)
  THROW 52335,N''Có ràng buộc chưa trusted hoặc trigger bị tắt.'',1;
 SELECT N''SqlV9Merged'' SchemaVersion,60 TableCount,
 (SELECT COUNT(*) FROM dbo.BANG_LUONG WHERE PhienBanTinhLuong=8) PreservedLegacyPayroll;
END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraSchema AS
BEGIN
 SET NOCOUNT ON;
 EXEC dbo.usp_RHM_KiemTraSchemaNen;
 EXEC dbo.usp_RHM_KiemTraKeThuoc;
 EXEC dbo.usp_RHM_KiemTraDongBoV9;
END;';
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.SqlV9.Version')
  EXEC sys.sp_updateextendedproperty @name=N'RHM.SqlV9.Version',@value=9;
 ELSE EXEC sys.sp_addextendedproperty @name=N'RHM.SqlV9.Version',@value=9;
 EXEC dbo.usp_RHM_KiemTraSchema;
 COMMIT TRANSACTION;
 EXEC sys.sp_set_session_context @key=N'RHM.SqlV9.Completed',@value=1;
 PRINT N'HOÀN TẤT: 60 bảng, lịch khám, chấm công, lương V9 và quy trình khám/thu tiền đã đồng bộ.';
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO

-- PHA 6: BẢO TRÌ ĐÚNG THIẾT BỊ/SERIAL. Chỉ thay đổi hai bảng thiết bị/bảo trì.
SET XACT_ABORT ON;
BEGIN TRY
 IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.SqlV9.Completed')),0)<>1
  THROW 52600,N'Phải hoàn tất các pha trước khi đồng bộ bảo trì theo serial.',1;
 BEGIN TRANSACTION;
 DECLARE @maintenanceInstalled bit=CASE WHEN EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.MaintenanceSerial.Version' AND TRY_CONVERT(int,value)=1) THEN 1 ELSE 0 END;
 IF COL_LENGTH(N'dbo.BAO_TRI_THIET_BI',N'NgayXacNhan') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI ADD NgayXacNhan datetime2(0) NULL;
 IF COL_LENGTH(N'dbo.BAO_TRI_THIET_BI',N'NgayThucHien') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI ADD NgayThucHien datetime2(0) NULL;
 IF @maintenanceInstalled=0
 BEGIN
  -- Ngày đã kết thúc trong dữ liệu cũ giữ nguyên; không suy đoán thời điểm xác nhận/thực hiện chưa được lưu.
  EXEC sys.sp_executesql N'
  IF EXISTS(SELECT 1 FROM dbo.THIET_BI WHERE NULLIF(LTRIM(RTRIM(SoSerial)),N'''') IS NULL)
   THROW 52601,N''Có thiết bị thiếu serial; cần nhập serial thật trước khi nâng cấp.'',1;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI WHERE TrangThai NOT IN(N''Nháp'',N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'',N''Hoàn thành'',N''Đã hoàn thành'',N''Hủy''))
   THROW 52601,N''Có trạng thái bảo trì cũ chưa xác định; cần đối chiếu, không tự xóa lịch sử.'',1;
  UPDATE dbo.BAO_TRI_THIET_BI SET TrangThai=CASE
   WHEN TrangThai=N''Nháp'' THEN N''Chưa xác nhận''
   WHEN TrangThai=N''Hoàn thành'' OR(TrangThai=N''Đã xác nhận'' AND NgayKetThuc IS NOT NULL) THEN N''Đã hoàn thành'' ELSE TrangThai END;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI WHERE TrangThai=N''Đã hoàn thành'' AND NgayKetThuc IS NULL)
   THROW 52601,N''Phiếu hoàn thành cũ thiếu ngày kết thúc; cần đối chiếu trước khi nâng cấp.'',1;
  -- Ngày kết thúc của nháp/lần đang làm cũ có thể là lịch dự kiến: giữ lại trong ghi chú trước khi dùng trường này cho kết quả thực tế.
  UPDATE dbo.BAO_TRI_THIET_BI SET GhiChu=CONCAT(GhiChu,N'' | Ngày kết thúc dự kiến trước đồng bộ: '',CONVERT(nvarchar(30),NgayKetThuc,126)),NgayKetThuc=NULL
   WHERE TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND NgayKetThuc IS NOT NULL;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI WHERE TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') GROUP BY MaTB HAVING COUNT(*)>1)
   THROW 52601,N''Một serial có nhiều phiếu đang mở; cần đối chiếu, không tự hủy phiếu.'',1;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b JOIN dbo.THIET_BI t ON t.MaTB=b.MaTB
   WHERE b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND(t.TinhTrang IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'') OR t.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')))
   THROW 52601,N''Thiết bị đã ngưng còn phiếu mở; cần đối chiếu trước khi nâng cấp.'',1;
  UPDATE dbo.THIET_BI SET TinhTrang=CASE
   WHEN TinhTrang IN(N''Tốt'',N''Bình thường'',N''Hoạt động tốt'') THEN N''Đang hoạt động''
   WHEN TinhTrang IN(N''Hỏng'',N''Cần bảo trì'') THEN N''Hư hại''
   WHEN TinhTrang=N''Ngừng sử dụng'' THEN N''Ngưng sử dụng'' ELSE TinhTrang END;
  UPDATE t SET TinhTrang=CASE WHEN EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WHERE b.MaTB=t.MaTB AND b.TrangThai=N''Đang thực hiện'') THEN N''Đang bảo trì'' ELSE N''Hư hại'' END
   FROM dbo.THIET_BI t WHERE EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WHERE b.MaTB=t.MaTB AND b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện''));
  UPDATE t SET TinhTrang=N''Hư hại'' FROM dbo.THIET_BI t WHERE t.TinhTrang=N''Đang bảo trì''
   AND NOT EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WHERE b.MaTB=t.MaTB AND b.TrangThai=N''Đang thực hiện'');
  IF EXISTS(SELECT 1 FROM dbo.THIET_BI WHERE TinhTrang NOT IN(N''Đang hoạt động'',N''Hư hại'',N''Đang bảo trì'',N''Ngưng sử dụng''))
   THROW 52601,N''Có tình trạng thiết bị chưa xác định; cần đối chiếu thay vì tự đổi dữ liệu.'',1;
  ';
 END;
 IF OBJECT_ID(N'dbo.CK_TB_Serial_KhongTrong',N'C') IS NULL
  ALTER TABLE dbo.THIET_BI WITH CHECK ADD CONSTRAINT CK_TB_Serial_KhongTrong CHECK(NULLIF(LTRIM(RTRIM(SoSerial)),N'') IS NOT NULL);
 IF OBJECT_ID(N'dbo.CK_TB_TinhTrang_BaoTri',N'C') IS NULL
  ALTER TABLE dbo.THIET_BI WITH CHECK ADD CONSTRAINT CK_TB_TinhTrang_BaoTri CHECK(TinhTrang IN(N'Đang hoạt động',N'Hư hại',N'Đang bảo trì',N'Ngưng sử dụng'));
 IF OBJECT_ID(N'dbo.CK_BT_VongDoi',N'C') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI WITH CHECK ADD CONSTRAINT CK_BT_VongDoi CHECK(TrangThai IN(N'Chưa xác nhận',N'Đã xác nhận',N'Đang thực hiện',N'Đã hoàn thành',N'Hủy'));
 IF OBJECT_ID(N'dbo.CK_BT_NoiDung',N'C') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI WITH CHECK ADD CONSTRAINT CK_BT_NoiDung CHECK(LEN(LTRIM(RTRIM(NoiDung)))>0);
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.BAO_TRI_THIET_BI') AND name=N'UX_BT_Serial_PhieuMo')
  CREATE UNIQUE INDEX UX_BT_Serial_PhieuMo ON dbo.BAO_TRI_THIET_BI(MaTB) WHERE TrangThai IN(N'Chưa xác nhận',N'Đã xác nhận',N'Đang thực hiện');
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_BT_Serial_VongDoi ON dbo.BAO_TRI_THIET_BI
 AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF TRIGGER_NESTLEVEL(OBJECT_ID(N''dbo.TR_BT_Serial_VongDoi''))>1 RETURN;
  IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaBT=d.MaBT WHERE i.MaBT IS NULL)
   THROW 52602,N''Không xóa lịch sử bảo trì; chỉ hủy phiếu Chưa xác nhận.'',1;
  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaBT=i.MaBT WHERE d.MaBT IS NULL AND i.TrangThai NOT IN(N''Chưa xác nhận'',N''Đã xác nhận''))
   THROW 52603,N''Phiếu mới chỉ được lưu Chưa xác nhận hoặc Đã xác nhận.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE d.TrangThai IN(N''Đã hoàn thành'',N''Hủy''))
   THROW 52604,N''Phiếu đã hoàn thành hoặc hủy chỉ được xem.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE i.MaTB<>d.MaTB)
   THROW 52604,N''Không chuyển phiếu sang thiết bị/serial khác.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE d.TrangThai<>N''Chưa xác nhận'' AND EXISTS(
   SELECT i.MaNV,i.NgayBatDau,i.NoiDung,i.ChiPhi,i.NgayBaoTriTiepTheo,i.GhiChu EXCEPT SELECT d.MaNV,d.NgayBatDau,d.NoiDung,d.ChiPhi,d.NgayBaoTriTiepTheo,d.GhiChu))
   THROW 52604,N''Không sửa nội dung phiếu đã xác nhận.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE i.TrangThai<>d.TrangThai AND NOT(
   (d.TrangThai=N''Chưa xác nhận'' AND i.TrangThai IN(N''Đã xác nhận'',N''Hủy''))
   OR(d.TrangThai=N''Đã xác nhận'' AND i.TrangThai=N''Đang thực hiện'')
   OR(d.TrangThai=N''Đang thực hiện'' AND i.TrangThai=N''Đã hoàn thành'')))
   THROW 52603,N''Chuyển trạng thái bảo trì không đúng vòng đời.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE EXISTS(SELECT i.NgayXacNhan,i.NgayThucHien,i.NgayKetThuc EXCEPT SELECT d.NgayXacNhan,d.NgayThucHien,d.NgayKetThuc))
   THROW 52604,N''Các thời điểm xác nhận, thực hiện và kết thúc do hệ thống ghi.'',1;
  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaBT=i.MaBT WHERE d.MaBT IS NULL AND(i.NgayXacNhan IS NOT NULL OR i.NgayThucHien IS NOT NULL OR i.NgayKetThuc IS NOT NULL))
   THROW 52604,N''Không tự nhập thời điểm kết thúc hoặc xác nhận phiếu mới.'',1;
  DECLARE @locked int;
  SELECT @locked=COUNT(*) FROM dbo.THIET_BI t WITH(UPDLOCK,HOLDLOCK) JOIN inserted i ON i.MaTB=t.MaTB;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.THIET_BI t ON t.MaTB=i.MaTB LEFT JOIN deleted d ON d.MaBT=i.MaBT
   WHERE (d.MaBT IS NULL OR d.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'')) AND i.TrangThai<>N''Hủy''
    AND(t.TinhTrang<>N''Hư hại'' OR t.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'') OR NULLIF(LTRIM(RTRIM(t.SoSerial)),N'''') IS NULL))
   THROW 52605,N''Chỉ lập/xác nhận/bắt đầu bảo trì serial đang Hư hại và chưa ngưng sử dụng.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE d.TrangThai=N''Đã xác nhận'' AND i.TrangThai=N''Đang thực hiện'' AND i.NgayBatDau>CONVERT(date,SYSDATETIME()))
   THROW 52605,N''Chưa đến ngày dự kiến bắt đầu bảo trì.'',1;
  DECLARE @now datetime2(0)=SYSDATETIME();
  UPDATE b SET
   NgayXacNhan=CASE WHEN i.TrangThai=N''Đã xác nhận'' AND(d.MaBT IS NULL OR d.TrangThai=N''Chưa xác nhận'') THEN @now ELSE b.NgayXacNhan END,
   NgayThucHien=CASE WHEN i.TrangThai=N''Đang thực hiện'' AND d.TrangThai=N''Đã xác nhận'' THEN @now ELSE b.NgayThucHien END,
   NgayKetThuc=CASE WHEN i.TrangThai=N''Đã hoàn thành'' AND d.TrangThai=N''Đang thực hiện'' THEN @now ELSE b.NgayKetThuc END
   FROM dbo.BAO_TRI_THIET_BI b JOIN inserted i ON i.MaBT=b.MaBT LEFT JOIN deleted d ON d.MaBT=i.MaBT;
  UPDATE t SET TinhTrang=CASE WHEN i.TrangThai=N''Đang thực hiện'' THEN N''Đang bảo trì'' ELSE N''Đang hoạt động'' END
   FROM dbo.THIET_BI t JOIN inserted i ON i.MaTB=t.MaTB JOIN deleted d ON d.MaBT=i.MaBT
   WHERE(d.TrangThai=N''Đã xác nhận'' AND i.TrangThai=N''Đang thực hiện'') OR(d.TrangThai=N''Đang thực hiện'' AND i.TrangThai=N''Đã hoàn thành'');
 END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_TB_Serial_BaoVe ON dbo.THIET_BI
 AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaTB=i.MaTB WHERE(i.SoSerial<>d.SoSerial OR i.MaHH<>d.MaHH) AND EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB))
   THROW 52606,N''Thiết bị đã có lịch sử bảo trì; không đổi serial hoặc nguồn hàng hóa.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaTB=i.MaTB WHERE d.TinhTrang=N''Ngưng sử dụng'' AND i.TinhTrang<>d.TinhTrang)
   THROW 52606,N''Thiết bị đã ngưng sử dụng không được tự khôi phục.'',1;
  IF EXISTS(SELECT 1 FROM inserted i WHERE i.TinhTrang=N''Đang bảo trì'' AND NOT EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB AND b.TrangThai=N''Đang thực hiện''))
   THROW 52606,N''Tình trạng Đang bảo trì chỉ được đặt khi thực hiện phiếu bảo trì.'',1;
  IF EXISTS(SELECT 1 FROM inserted i WHERE EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB AND(
   (b.TrangThai=N''Đang thực hiện'' AND i.TinhTrang<>N''Đang bảo trì'') OR(b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'') AND i.TinhTrang<>N''Hư hại'')
   OR(b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND i.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')))))
   THROW 52606,N''Thiết bị đang có phiếu mở; cập nhật tình trạng qua Lịch sử bảo trì.'',1;
 END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraBaoTriSerial AS
 BEGIN
  SET NOCOUNT ON;
  IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''RHM.MaintenanceSerial.Version'' AND TRY_CONVERT(int,value)=1)
   THROW 52600,N''Chưa đồng bộ bảo trì serial; chạy toàn bộ QLBenhVienRangHamMat.sql.'',1;
  IF EXISTS(SELECT 1 FROM (VALUES(N''NgayXacNhan''),(N''NgayThucHien'')) e(N) LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N''dbo.BAO_TRI_THIET_BI'') AND c.name=e.N
   WHERE c.column_id IS NULL OR TYPE_NAME(c.user_type_id)<>N''datetime2'' OR c.scale<>0 OR c.is_nullable<>1)
   THROW 52600,N''Thiếu hoặc sai kiểu thời điểm xác nhận/thực hiện bảo trì.'',1;
  IF EXISTS(SELECT 1 FROM (VALUES(N''UQ_THIET_BI_SoSerial'',N''UQ''),(N''CK_TB_Serial_KhongTrong'',N''C''),(N''CK_TB_TinhTrang_BaoTri'',N''C''),(N''CK_BT_VongDoi'',N''C''),(N''CK_BT_NoiDung'',N''C''),
   (N''FK_BAO_TRI_THIET_BI_MaTB'',N''F''),(N''FK_BAO_TRI_THIET_BI_MaNV'',N''F''),(N''TR_BT_Serial_VongDoi'',N''TR''),(N''TR_TB_Serial_BaoVe'',N''TR'')) e(N,T) WHERE OBJECT_ID(N''dbo.''+e.N,e.T) IS NULL)
   THROW 52600,N''Thiếu liên kết hoặc bảo vệ bảo trì theo serial.'',1;
  IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.BAO_TRI_THIET_BI'') AND name=N''UX_BT_Serial_PhieuMo'' AND is_unique=1 AND has_filter=1 AND is_disabled=0
   AND filter_definition LIKE N''%Chưa xác nhận%'' AND filter_definition LIKE N''%Đã xác nhận%'' AND filter_definition LIKE N''%Đang thực hiện%'')
   OR NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.THIET_BI'') AND name=N''UQ_THIET_BI_SoSerial'' AND is_unique=1 AND is_disabled=0)
   OR EXISTS(SELECT 1 FROM sys.triggers WHERE name IN(N''TR_BT_Serial_VongDoi'',N''TR_TB_Serial_BaoVe'') AND is_disabled=1)
   OR EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id IN(OBJECT_ID(N''dbo.BAO_TRI_THIET_BI''),OBJECT_ID(N''dbo.THIET_BI'')) AND(is_disabled=1 OR is_not_trusted=1))
   OR EXISTS(SELECT 1 FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N''dbo.BAO_TRI_THIET_BI'') AND(is_disabled=1 OR is_not_trusted=1))
   THROW 52600,N''Index/ràng buộc/trigger bảo trì bị tắt hoặc chưa trusted.'',1;
 END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraSchema AS
 BEGIN
  SET NOCOUNT ON;
  EXEC dbo.usp_RHM_KiemTraSchemaNen;
  EXEC dbo.usp_RHM_KiemTraKeThuoc;
  EXEC dbo.usp_RHM_KiemTraDongBoV9;
  EXEC dbo.usp_RHM_KiemTraBaoTriSerial;
 END;';
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.MaintenanceSerial.Version')
  EXEC sys.sp_updateextendedproperty @name=N'RHM.MaintenanceSerial.Version',@value=1;
 ELSE EXEC sys.sp_addextendedproperty @name=N'RHM.MaintenanceSerial.Version',@value=1;
 EXEC dbo.usp_RHM_KiemTraBaoTriSerial;
 COMMIT TRANSACTION;
 PRINT N'HOÀN TẤT BẢO TRÌ SERIAL: liên kết thiết bị, vòng đời phiếu và tình trạng vật lý đã đồng bộ.';
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO
